const SearchTool={postalcode:null,init:async function(t={}){this.postalcode=document.getElementById("searchtool_postalcode"),this.postalcode.addEventListener("input",()=>{let e=this.postalcode.value.replace(/\s/g,"");e.length>3&&(e=e.slice(0,3)+" "+e.slice(3)),this.postalcode.value=e.toUpperCase(),this.postalcode.checkValidity()&&this.searchSection(this.postalcode.value)})},searchSection:async function(t){console.log("Rechercher: "+t)}};
